use mindtrail_lib::protocol::*;
use serde_json::{json,Value};
use std::collections::HashMap;
#[derive(Default)] struct Store { meta:Option<SessionMetadata>, events:HashMap<u64,Value>, ops:HashMap<String,(Value,u64)>, nodes:HashMap<String,NodeKind> }
impl SessionSnapshot for Store { fn metadata(&self)->&SessionMetadata {self.meta.as_ref().unwrap()} fn event(&self,n:u64)->Result<Option<Value>,ProtocolError>{Ok(self.events.get(&n).cloned())} fn operation(&self,id:&str)->Result<Option<(Value,u64)>,ProtocolError>{Ok(self.ops.get(id).cloned())} fn node_kind(&self,id:&str)->Result<Option<NodeKind>,ProtocolError>{Ok(self.nodes.get(id).copied())} }
impl Store {fn snapshot(&self)->Option<&dyn SessionSnapshot>{self.meta.as_ref().map(|_|self as &dyn SessionSnapshot)} fn commit<R>(&mut self,p:WritePlan<R>){for v in p.events {self.events.insert(v["seq"].as_u64().unwrap(),v);} for o in p.operations {self.ops.insert(o.operation_id,(o.input,o.seq));} self.nodes.extend(p.node_updates);self.meta=Some(p.metadata);}}
fn event(n:u64,k:&str,p:Value)->Value {json!({"v":1,"session":"s","seq":n,"ts":"2024-01-01T00:00:00Z","type":k,"payload":p})}
fn explicit(v:Vec<Value>)->ExplicitBatch {decode_explicit(&serde_json::to_vec(&v).unwrap()).unwrap()}
fn append(v:Vec<Value>)->AppendBatch {decode_append(&serde_json::to_vec(&v).unwrap()).unwrap()}
fn op(id:&str,k:&str,p:Value)->Value {let mut v=event(1,k,p);v.as_object_mut().unwrap().remove("seq");v["operation_id"]=id.into();v}
fn start(n:u64)->Value {event(n,"task.start",json!({"title":"t","goal":"g","project":"p"}))}
#[test] fn atomic_lifecycle_and_retries(){let mut s=Store::default();let fact=event(1,"task.done",json!({}));assert_eq!(plan_explicit(&explicit(vec![fact]),None).unwrap_err().code,"task_not_started");let e=plan_explicit(&explicit(vec![start(2)]),None).unwrap_err();assert_eq!((e.code,e.expected_seq,e.offending_seq,e.last_seq,e.index),("seq_gap",Some(1),Some(2),Some(0),Some(0)));s.commit(plan_explicit(&explicit(vec![start(1)]),None).unwrap());let two=event(2,"capability.intent",json!({"id":"c","title":"c"}));let three=event(3,"task.done",json!({}));let e=plan_explicit(&explicit(vec![two.clone(),event(4,"task.done",json!({}))]),s.snapshot()).unwrap_err();assert_eq!((e.index,e.expected_seq,e.last_seq),(Some(1),Some(3),Some(1)));assert_eq!(s.meta.as_ref().unwrap().last_seq,1);let p=plan_explicit(&explicit(vec![two,three]),s.snapshot()).unwrap();assert_eq!((p.receipt.accepted,p.receipt.last_seq),(2,3));s.commit(p);let p=plan_explicit(&explicit(vec![start(1)]),s.snapshot()).unwrap();assert_eq!((p.receipt.duplicates,p.receipt.last_seq),(1,3));let mut changed=start(1);changed["ts"]="2024-01-01T00:00:00+00:00".into();assert_eq!(plan_explicit(&explicit(vec![changed]),s.snapshot()).unwrap_err().code,"seq_conflict");assert_eq!(plan_explicit(&explicit(vec![event(4,"task.done",json!({}))]),s.snapshot()).unwrap_err().code,"task_closed");}
#[test] fn nodes_and_atomic_tail(){let mut s=Store::default();let cap=event(2,"capability.intent",json!({"id":"c","title":"c"}));let api=event(3,"api.expose",json!({"id":"a","kind":"fn","signature":"f"}));let file=event(4,"file.change",json!({"id":"f","path":"p","action":"create","stats":{"add":0,"del":0}}));let edge=event(5,"call.edge",json!({"from":"a","to":"f","kind":"calls"}));let p=plan_explicit(&explicit(vec![start(1),cap,api,file,edge]),None).unwrap();s.commit(p);for (k,p,code) in [("capability.done",json!({"id":"a"}),"invalid_reference"),("call.edge",json!({"from":"c","to":"a","kind":"calls"}),"invalid_reference"),("api.expose",json!({"id":"c","kind":"fn","signature":"f"}),"node_id_conflict"),("capability.intent",json!({"id":"root","title":"x"}),"node_id_conflict"),("task.start",json!({"title":"t","goal":"g","project":"p"}),"task_already_started")] {assert_eq!(plan_explicit(&explicit(vec![event(6,k,p)]),s.snapshot()).unwrap_err().code,code)} assert_eq!(plan_explicit(&explicit(vec![event(6,"task.done",json!({})),event(7,"task.done",json!({}))]),s.snapshot()).unwrap_err().code,"task_closed");assert_eq!(s.meta.unwrap().last_seq,5);}
#[test] fn append_replay_and_exhaustion(){let mut s=Store::default();let a=op("a","task.start",json!({"title":"t","goal":"g","project":"p"}));let b=op("b","task.done",json!({}));s.commit(plan_append(&append(vec![a.clone()]),None).unwrap());let p=plan_append(&append(vec![a.clone(),b.clone()]),s.snapshot()).unwrap();assert_eq!(p.receipt.results.iter().map(|x|x.seq).collect::<Vec<_>>(),vec![1,2]);s.commit(p);assert_eq!(plan_append(&append(vec![a.clone()]),s.snapshot()).unwrap().receipt.duplicates,1);let mut changed=a;changed["ts"]="2024-01-01T00:00:00+00:00".into();assert_eq!(plan_append(&append(vec![changed]),s.snapshot()).unwrap_err().code,"operation_conflict");assert_eq!(plan_explicit(&explicit(vec![start(1)]),s.snapshot()).unwrap_err().code,"write_mode_conflict");s.meta.as_mut().unwrap().last_seq=MAX_SAFE_INTEGER;assert_eq!(plan_append(&append(vec![b]),s.snapshot()).unwrap().receipt.duplicates,1);assert_eq!(plan_append(&append(vec![op("new","task.done",json!({}))]),s.snapshot()).unwrap_err().code,"task_closed");s.meta.as_mut().unwrap().status=SessionStatus::Running;assert_eq!(plan_append(&append(vec![op("new","task.done",json!({}))]),s.snapshot()).unwrap_err().code,"seq_exhausted");}
struct Failing<'a> { store:&'a Store, kind:&'static str }
impl SessionSnapshot for Failing<'_> { fn metadata(&self)->&SessionMetadata {self.store.metadata()} fn event(&self,n:u64)->Result<Option<Value>,ProtocolError>{if self.kind=="event" && n==3 {Err(temporary_storage_error("lookup failed"))}else{self.store.event(n)}} fn operation(&self,id:&str)->Result<Option<(Value,u64)>,ProtocolError>{if self.kind=="operation" && id=="bad" {Err(temporary_storage_error("lookup failed"))}else{self.store.operation(id)}} fn node_kind(&self,id:&str)->Result<Option<NodeKind>,ProtocolError>{if self.kind=="node" && id=="bad" {Err(temporary_storage_error("lookup failed"))}else{self.store.node_kind(id)}} }
#[test] fn lookup_failures_preserve_error_and_discard_overlay(){for kind in ["event","node","operation"] {let mut s=Store::default();let a=op("start","task.start",json!({"title":"t","goal":"g","project":"p"}));if kind=="operation" {s.commit(plan_append(&append(vec![a]),None).unwrap())} else {s.commit(plan_explicit(&explicit(vec![start(1)]),None).unwrap())} let first=event(2,"capability.intent",json!({"id":"new","title":"new"}));let second=event(3,"capability.done",json!({"id":"bad"}));let f=Failing{store:&s,kind};let err=if kind=="operation" {plan_append(&append(vec![op("new","capability.intent",json!({"id":"new","title":"new"})),op("bad","task.done",json!({}))]),Some(&f)).unwrap_err()}else{plan_explicit(&explicit(vec![first.clone(),second.clone()]),Some(&f)).unwrap_err()};assert_eq!((err.code,err.status(),err.index,err.message.as_str()),("temporary_storage",503,Some(1),"lookup failed"));assert_eq!(s.meta.as_ref().unwrap().last_seq,1);assert!(s.nodes.is_empty());if kind=="operation" {assert!(plan_append(&append(vec![op("new","capability.intent",json!({"id":"new","title":"new"})),op("bad","task.done",json!({}))]),s.snapshot()).is_ok())} else {let valid=event(3,"capability.done",json!({"id":"new"}));assert!(plan_explicit(&explicit(vec![first,valid]),s.snapshot()).is_ok())}}}
#[test] fn remaining_contract_cases(){let mut s=Store::default();let original=start(1);s.commit(plan_explicit(&explicit(vec![original.clone()]),None).unwrap());let reordered=br#"[ { "payload": {"project":"p", "goal":"g", "title":"t"}, "type":"task.start", "ts":"2024-01-01T00:00:00Z", "seq":1, "session":"s", "v":1 } ]"#;assert_eq!(plan_explicit(&decode_explicit(reordered).unwrap(),s.snapshot()).unwrap().receipt.duplicates,1);for change in [json!({"title":"different","goal":"g","project":"p"}),json!({"title":"t","goal":"g","project":"p","quote":"x"})] {let mut v=original.clone();v["payload"]=change;assert_eq!(plan_explicit(&explicit(vec![v]),s.snapshot()).unwrap_err().code,"seq_conflict")}for v in [event(2,"capability.done",json!({"id":"missing"})),event(2,"call.edge",json!({"from":"missing","to":"missing","kind":"calls"}))] {assert_eq!(plan_explicit(&explicit(vec![v]),s.snapshot()).unwrap_err().code,"invalid_reference")}let p=plan_explicit(&explicit(vec![event(2,"capability.intent",json!({"id":"c","title":"c"})),event(3,"capability.intent",json!({"id":"c","title":"again"})),event(4,"api.expose",json!({"id":"a","kind":"fn","signature":"f","capabilityId":"unknown"})),event(5,"task.done",json!({}))]),s.snapshot()).unwrap();s.commit(p);assert_eq!(plan_explicit(&explicit(vec![original]),s.snapshot()).unwrap().receipt.last_seq,5);assert_eq!(plan_explicit(&explicit(vec![event(7,"task.done",json!({}))]),s.snapshot()).unwrap_err().code,"seq_gap");assert_eq!(plan_explicit(&explicit(vec![start(1),event(2,"task.done",json!({})),event(3,"task.done",json!({}))]),None).unwrap_err().code,"task_closed");}
#[test] fn append_interleaves_new_and_old(){let mut s=Store::default();let a=op("a","task.start",json!({"title":"t","goal":"g","project":"p"}));s.commit(plan_append(&append(vec![a.clone()]),None).unwrap());let p=plan_append(&append(vec![op("b","capability.intent",json!({"id":"c","title":"c"})),a,op("c","task.done",json!({}))]),s.snapshot()).unwrap();assert_eq!(p.receipt.results.iter().map(|r|r.seq).collect::<Vec<_>>(),vec![2,1,3]);}
#[test] fn start_and_done_in_one_batch_succeeds(){let p=plan_explicit(&explicit(vec![start(1),event(2,"task.done",json!({}))]),None).unwrap();assert_eq!((p.receipt.accepted,p.receipt.duplicates,p.receipt.last_seq,p.metadata.status),(2,0,2,SessionStatus::Done));}
#[test] fn resend_after_gap_has_no_duplicates(){let mut s=Store::default();s.commit(plan_explicit(&explicit(vec![start(1)]),None).unwrap());let a=event(2,"capability.intent",json!({"id":"c","title":"c"}));assert_eq!(plan_explicit(&explicit(vec![a.clone(),event(4,"task.done",json!({}))]),s.snapshot()).unwrap_err().code,"seq_gap");let p=plan_explicit(&explicit(vec![a,event(3,"task.done",json!({}))]),s.snapshot()).unwrap();assert_eq!((p.receipt.accepted,p.receipt.duplicates,p.receipt.last_seq),(2,0,3));}

#[test] fn mismatched_snapshots_and_reverse_mode(){let mut s=Store::default();s.commit(plan_explicit(&explicit(vec![start(1)]),None).unwrap());let mut v=event(2,"task.done",json!({}));v["session"]="other".into();let e=plan_explicit(&explicit(vec![v]),s.snapshot()).unwrap_err();assert_eq!((e.code,e.status()),("storage_invariant",500));let mut a=op("a","task.done",json!({}));a["session"]="other".into();assert_eq!(plan_append(&append(vec![a]),s.snapshot()).unwrap_err().code,"storage_invariant");assert_eq!(plan_append(&append(vec![op("a","task.done",json!({}))]),s.snapshot()).unwrap_err().code,"write_mode_conflict");}
